// Headers

#include <iostream>   // provides standard input and output streams (cin, cout, cerr)
#include <fstream>    // allows reading from and writing to external files
#include <string>     // provides the std::string class for text manipulation
#include <cctype>     // includes character classification functions like std::toupper
#include <vector>     // provides the std::vector dynamic array container for the heap
#include <utility>    // provides std::move to transfer resources efficiently

// Email class

class Email {
private: // restricts access to these variables so they cannot be modified outside the class
    std::string senderCategory;
    std::string subjectLine;
    std::string dateReceived;
    int categoryRank;
    int dateValue;
    long arrivalOrder;

    // converts a category string into a numeric rank for priority comparison
    static int rankFromCategory(const std::string& categoryText) {
        // assigns highest priority rank to boss
        if (categoryText == "Boss") return 5;
        // assigns second highest priority to subordinate
        if (categoryText == "Subordinate") return 4;
        // assigns medium priority to peer
        if (categoryText == "Peer") return 3;
        // assigns lower priority to important person
        if (categoryText == "ImportantPerson") return 2;
        // assigns lowest priority to any other category
        return 1;
    }

    // converts "MM-DD-YYYY" string format into the integer YYYYMMDD for easy numeric comparison
    static int valueFromDate(const std::string& dateText) {
        // checks if the date string is at least 10 characters long to prevent out-of-bounds errors
        if (dateText.size() < 10) {
            std::cerr << "Error: improperly formatted date string '" << dateText << "'. Defaulting to 0.\n";
            return 0;
        }
        try {
            // extracts the first two characters and converts them to an integer for the month
            int monthValue = std::stoi(dateText.substr(0, 2));
            // extracts the middle two characters and converts them to an integer for the day
            int dayValue = std::stoi(dateText.substr(3, 2));
            // extracts the last four characters and converts them to an integer for the year
            int yearValue = std::stoi(dateText.substr(6, 4));
            // mathematically combines the values so the year is the most significant digit, followed by month and day
            return yearValue * 10000 + monthValue * 100 + dayValue;
        } catch (...) {
            // catches any exceptions thrown by std::stoi if the substring contains non-numeric characters
            std::cerr << "Error: improperly formatted date string '" << dateText << "'. Defaulting to 0.\n";
            return 0;
        }
    }

public: // allows external code to access the functions below
    // default constructor initializes numeric fields to zero to prevent undefined behavior
    Email() : categoryRank(0), dateValue(0), arrivalOrder(0) {}

    // constructor taking values by value to optimize std::move operations
    Email(std::string categoryText, std::string subjectText, std::string dateText, long currentArrivalOrder)
        // std::move transfers ownership of the string memory rather than copying it, saving execution time
        : senderCategory(std::move(categoryText)), 
          subjectLine(std::move(subjectText)), 
          dateReceived(std::move(dateText)),
          // calculates and stores the numeric rank based on the moved category string
          categoryRank(rankFromCategory(senderCategory)),
          // calculates and stores the numeric date based on the moved date string
          dateValue(valueFromDate(dateReceived)),
          // stores the exact order this email was parsed to break ties
          arrivalOrder(currentArrivalOrder) {}

    // returns true if this email should be read before the other email
    bool hasHigherPriorityThan(const Email& otherEmail) const {
        // if the categories are different, the higher numeric rank wins
        if (categoryRank != otherEmail.categoryRank)
            return categoryRank > otherEmail.categoryRank;
        // if categories are the same but dates differ, the newer (larger) date wins
        if (dateValue != otherEmail.dateValue)
            return dateValue > otherEmail.dateValue;
        // if both category and date are identical, the email that arrived first wins
        return arrivalOrder < otherEmail.arrivalOrder;
    }

    // prints the email in the required output format
    void display() const {
        std::cout << "Sender: " << senderCategory << "\n";
        std::cout << "Subject: " << subjectLine << "\n";
        std::cout << "Date: " << dateReceived << "\n";
    }
};

// MaxHeap class

class MaxHeap {
private:
    // dynamic array used to represent the binary tree structure of the heap
    std::vector<Email> heapItems;

    // moves an element up the tree until the heap property is restored
    void siftUp(size_t currentIndex) {
        // loops as long as the current item is not the root of the tree
        while (currentIndex > 0) {
            // calculates the index of the parent node in a zero-indexed binary heap
            size_t parentIndex = (currentIndex - 1) / 2;
            // checks if the child has a higher priority than its parent
            if (heapItems[currentIndex].hasHigherPriorityThan(heapItems[parentIndex])) {
                // temporarily stores the child email using move semantics
                Email temporaryEmail = std::move(heapItems[currentIndex]);
                // moves the parent down into the child's position
                heapItems[currentIndex] = std::move(heapItems[parentIndex]);
                // moves the temporarily stored child up into the parent's position
                heapItems[parentIndex] = std::move(temporaryEmail);
                // updates the current index to the parent's index to continue checking upward
                currentIndex = parentIndex;
            } else {
                // breaks the loop if the heap property is satisfied
                break;
            }
        }
    }

    // moves an element down the tree until the heap property is restored
    void siftDown(size_t currentIndex) {
        // stores the total number of items to prevent out-of-bounds access
        size_t totalItems = heapItems.size();
        while (true) {
            // calculates the index of the left child
            size_t leftChildIndex = 2 * currentIndex + 1;
            // calculates the index of the right child
            size_t rightChildIndex = 2 * currentIndex + 2;
            // assumes the current node has the highest priority initially
            size_t highestPriorityIndex = currentIndex;

            // checks if the left child exists and has a higher priority than the current highest
            if (leftChildIndex < totalItems && heapItems[leftChildIndex].hasHigherPriorityThan(heapItems[highestPriorityIndex]))
                highestPriorityIndex = leftChildIndex;
            // checks if the right child exists and has a higher priority than the current highest
            if (rightChildIndex < totalItems && heapItems[rightChildIndex].hasHigherPriorityThan(heapItems[highestPriorityIndex]))
                highestPriorityIndex = rightChildIndex;
            // breaks the loop if the current node is already correctly positioned
            if (highestPriorityIndex == currentIndex) break;

            // temporarily stores the current email
            Email temporaryEmail = std::move(heapItems[currentIndex]);
            // moves the highest priority child up into the current node's position
            heapItems[currentIndex] = std::move(heapItems[highestPriorityIndex]);
            // moves the current email down into the child's position
            heapItems[highestPriorityIndex] = std::move(temporaryEmail);
            // updates the current index to continue checking downward
            currentIndex = highestPriorityIndex;
        }
    }

public:
    // adds a new email to the priority queue
    void insert(Email newEmail) {
        // adds the new email to the very end of the dynamic array
        heapItems.push_back(std::move(newEmail));
        // restores the heap property by sifting the new element up
        siftUp(heapItems.size() - 1);
    }

    // checks if there are no emails in the queue
    bool isEmpty() const {
        return heapItems.empty();
    }

    // returns the total number of unread emails
    size_t size() const {
        return heapItems.size();
    }

    // looks at the highest priority email without removing it
    const Email& peek() const {
        // the highest priority element is always at the root (index 0)
        return heapItems[0];
    }

    // removes the highest priority email from the queue
    void removeTop() {
        // does nothing if the queue is already empty
        if (heapItems.empty()) return;
        // overwrites the root with the last element in the array
        heapItems[0] = std::move(heapItems.back());
        // removes the last element from the array to shrink its size
        heapItems.pop_back();
        // restores the heap property by sifting the new root downward
        if (!heapItems.empty()) siftDown(0);
    }
};

// CommandProcessor class

class CommandProcessor {
private:
    MaxHeap emailInbox;
    long nextArrivalOrder;

    // removes leading/trailing spaces, tabs, and carriage returns from a string
    static std::string trim(const std::string& inputString) {
        // defines all characters considered to be whitespace
        const std::string whitespaceChars = " \t\r\n";
        // finds the index of the first character that is not a whitespace
        size_t startIndex = inputString.find_first_not_of(whitespaceChars);
        // returns an empty string if the input was entirely whitespace
        if (startIndex == std::string::npos) return "";
        // finds the index of the last character that is not a whitespace
        size_t endIndex = inputString.find_last_not_of(whitespaceChars);
        // extracts and returns only the visible characters in the middle
        return inputString.substr(startIndex, endIndex - startIndex + 1);
    }

    // returns an upper-case copy of a string for case-insensitive comparisons
    static std::string toUpper(std::string inputString) {
        // iterates through every character in the string
        for (size_t charIndex = 0; charIndex < inputString.size(); charIndex++)
            // converts the character to uppercase and casts it back to char type
            inputString[charIndex] = (char)std::toupper((unsigned char)inputString[charIndex]);
        return inputString;
    }

    // handles an "EMAIL <category>,<subject>,<date>" line without stringstream overhead
    void handleEmail(const std::string& remainingText, std::string& categoryBuffer, std::string& subjectBuffer, std::string& dateBuffer) {
        // finds the location of the first comma delimiter
        size_t firstCommaIndex = remainingText.find(',');
        // exits the function if the formatting is invalid and no comma is found
        if (firstCommaIndex == std::string::npos) return;
        // finds the location of the second comma delimiter by searching after the first one
        size_t secondCommaIndex = remainingText.find(',', firstCommaIndex + 1);
        // exits the function if the formatting is invalid and a second comma is missing
        if (secondCommaIndex == std::string::npos) return;

        // extracts and trims the text before the first comma
        categoryBuffer = trim(remainingText.substr(0, firstCommaIndex));
        // extracts and trims the text between the first and second commas
        subjectBuffer = trim(remainingText.substr(firstCommaIndex + 1, secondCommaIndex - firstCommaIndex - 1));
        // extracts and trims the text after the second comma
        dateBuffer = trim(remainingText.substr(secondCommaIndex + 1));

        // constructs a new email using the parsed buffers and inserts it into the heap
        emailInbox.insert(Email(std::move(categoryBuffer), std::move(subjectBuffer), std::move(dateBuffer), nextArrivalOrder++));
    }

    // handles the NEXT command
    void handleNext() {
        // gracefully catches cases where the user asks for next email but the inbox is empty
        if (emailInbox.isEmpty()) {
            std::cout << "There are no emails to read.\n";
            return;
        }
        std::cout << "Next email:\n";
        // displays the highest priority email
        emailInbox.peek().display();
    }

    // handles the READ command
    void handleRead() {
        // discards the top email
        emailInbox.removeTop();
    }

    // handles the COUNT command
    void handleCount() {
        // outputs the current total size of the heap
        std::cout << "There are " << emailInbox.size() << " emails to read.\n";
    }

public:
    // initializes the arrival order tracker to zero upon processor creation
    CommandProcessor() : nextArrivalOrder(0) {}

    // parses the input file stream line by line
    void run(std::istream& inputStream) {
        std::string currentLine;
        std::string commandWord;
        std::string remainingText;
        
        // hoisted buffer strings to avoid memory reallocations during loop iterations
        std::string categoryBuffer;
        std::string subjectBuffer;
        std::string dateBuffer;

        // flag used to check for UTF-8 Byte Order Marks on the very first line
        bool isFirstLine = true;
        
        // loops continuously as long as a line can be read from the file
        while (std::getline(inputStream, currentLine)) {
            // checks if the first line starts with the invisible 3-byte BOM sequence
            if (isFirstLine && currentLine.compare(0, 3, "\xEF\xBB\xBF") == 0)
                // removes the BOM characters so parsing works correctly
                currentLine.erase(0, 3);
            isFirstLine = false;
            
            // removes leading and trailing whitespace from the current line
            currentLine = trim(currentLine);
            // skips the rest of the loop block if the line is completely empty
            if (currentLine.empty()) continue;
            
            // finds where the first command word ends
            size_t splitIndex = currentLine.find_first_of(" \t");
            // isolates the command word and capitalizes it to handle case variations
            commandWord = toUpper(currentLine.substr(0, splitIndex));
            // uses a ternary operator to either extract the remaining arguments or set them to empty if none exist
            remainingText = (splitIndex == std::string::npos) ? "" : trim(currentLine.substr(splitIndex));
            
            // routes the extracted command to the appropriate handler function
            if (commandWord == "EMAIL") {
                handleEmail(remainingText, categoryBuffer, subjectBuffer, dateBuffer);
            } else if (commandWord == "NEXT") {
                handleNext();
            } else if (commandWord == "READ") {
                handleRead();
            } else if (commandWord == "COUNT") {
                handleCount();
            } else {
                // logs a warning if a string other than the four valid commands is found
                std::cerr << "Warning: unrecognized line ignored: " << currentLine << "\n";
            }
        }
        // flushes the output buffer to ensure all text prints to the terminal immediately
        std::cout.flush();
    }
};

// main function

int main() {
    std::string inputFileName;
    std::cout << "Enter the name of the input file: ";
    // captures user input including spaces into the inputFileName variable
    std::getline(std::cin, inputFileName);
    
    // instantiates the CommandProcessor object
    CommandProcessor textProcessor;
    // attempts to open the file stream using the user-provided filename
    std::ifstream inputFileStream(inputFileName);
    
    // error handling block if the file does not exist or cannot be accessed
    if (!inputFileStream) {
        std::cerr << "Error: cannot open file " << inputFileName << "\n";
        // returns a non-zero exit code indicating failure
        return 1;
    }
    
    // passes the open file stream into the processor to begin execution
    textProcessor.run(inputFileStream);
    // terminates the program successfully
    return 0;
}